vs(vs_id, system, code) AS (VALUES
  ('VS_GOUT', 'http://hl7.org/fhir/sid/icd-10-cm', 'M10.00'),
  ('VS_GOUT', 'http://hl7.org/fhir/sid/icd-10-cm', 'M10.071'),
