  ('VS_TYPE_2_DIABETES_MELLITUS', 'http://hl7.org/fhir/sid/icd-10-cm', 'E11.9'),
  ('VS_URATE_LOWERING_THERAPY', 'http://www.whocc.no/atc', 'M04AA01'),
  ('VS_URATE_LOWERING_THERAPY', 'http://www.whocc.no/atc', 'M04AA03'),
