  WHERE EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_SERUM_URATE' AND vs.system = o.system AND vs.code = o.code))) o WHERE rn = 1),
-- GOUT-COH-INC-02 (inclusion): 一年內最近一次血清尿酸值大於或等於 6.0 mg/dL。
c_gout_coh_inc_02 AS (
  SELECT b.pid, b.index_date, a_gout_coh_inc_02_1.v AS v,
