  LEFT JOIN a_gout_coh_inc_03_1 ON a_gout_coh_inc_03_1.pid = b.pid AND a_gout_coh_inc_03_1.index_date = b.index_date),
a_gout_coh_inc_04_1 AS (
  SELECT b.pid, b.index_date, count(*) AS n,
